<?php $admin_title='Newsletter Subscribers';include '_header.php';$rows=$pdo->query('SELECT * FROM newsletter_subscribers ORDER BY id DESC')->fetchAll();?><div class="panel"><div class="panel-head"><h2>Subscribers</h2><span style="color:#798da4"><?=count($rows)?> records</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Name</th><th>Email</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><span class="badge green"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div><?php include '_footer.php'; ?>